namespace sv_686a7e52f5324cf1bfdb818cd459a5f9.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Holds the currently selected warehouse for a single user circuit.
/// Registered as Scoped so each Blazor Server circuit gets its own instance.
/// </summary>
public class WarehouseStateService
{
    public static readonly IReadOnlyList<WarehouseInfo> AvailableWarehouses =
    [
        new() { Id = "WH-A", Name = "Warehouse A" },
        new() { Id = "WH-B", Name = "Warehouse B" },
        new() { Id = "WH-C", Name = "Warehouse C" },
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public WarehouseInfo CurrentWarehouse =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId);

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_686a7e52f5324cf1bfdb818cd459a5f9.Services;

/// <summary>
/// Provides low-stock alert counts and notifies all subscribers when new data arrives.
/// Scoped per circuit so each user gets independent alert state.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private int _lastCount;

    public int CurrentCount => _lastCount;

    /// <summary>Fired whenever fresh alert data is available.</summary>
    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate varying results per warehouse
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches new data and notifies all subscribers.
    /// Called by the polling component; all other subscribers react through the event.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        _lastCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        // Clear delegates to avoid leaks
        OnAlertCountChanged = null;
    }
}

@using sv_686a7e52f5324cf1bfdb818cd459a5f9.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState

<div class="d-flex align-items-center">
    <label class="me-2 mb-0 text-nowrap fw-semibold" for="warehouse-select">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }
}

@using sv_686a7e52f5324cf1bfdb818cd459a5f9.Services
@rendermode InteractiveServer
@implements IDisposable
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState

<span class="badge rounded-pill @BadgeClass">@AlertService.CurrentCount</span>

@code {
    private string BadgeClass =>
        AlertService.CurrentCount > 0 ? "bg-danger" : "bg-success";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private void HandleAlertChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately refresh alerts when the warehouse changes
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

@page "/dashboard"
@using sv_686a7e52f5324cf1bfdb818cd459a5f9.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 28rem;">
    <div class="card-body">
        <h5 class="card-title">
            @Warehouse.Name
            <span class="text-muted fs-6">(@Warehouse.Id)</span>
        </h5>

        <p class="card-text mt-3">
            Low-stock alerts:
            <span class="badge rounded-pill @BadgeClass fs-6">@AlertService.CurrentCount</span>
        </p>

        <p class="text-muted small mb-0">
            Polling every 10 seconds. Last update: @_lastRefresh.ToString("T")
        </p>
    </div>
</div>

@code {
    private CancellationTokenSource _cts = new();
    private DateTime _lastRefresh;

    private WarehouseInfo Warehouse => WarehouseState.CurrentWarehouse;
    private string BadgeClass =>
        AlertService.CurrentCount > 0 ? "bg-danger" : "bg-success";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            _lastRefresh = DateTime.Now;
            StateHasChanged();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            _lastRefresh = DateTime.Now;
            await InvokeAsync(StateHasChanged);
        }
    }

    private void HandleAlertChanged()
    {
        _lastRefresh = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private async void HandleWarehouseChanged()
    {
        // Restart polling for the new warehouse
        await _cts.CancelAsync();
        _cts.Dispose();
        _cts = new CancellationTokenSource();

        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        _lastRefresh = DateTime.Now;
        await InvokeAsync(StateHasChanged);
        _ = PollAsync(_cts.Token);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnChange -= HandleWarehouseChanged;
        _cts.Cancel();
        _cts.Dispose();
    }
}

